// TestSpecPinsSection7PlantsAnUnpinnedRule is the §7 guard's own reversed
// witness: with the plant out the real spec has no findings, and with a new
// normative sentence in §7 and no row id the guard is red on that sentence.
func TestSpecPinsSection7PlantsAnUnpinnedRule(t *testing.T) {
	t.Parallel()
	root := repoRoot(t)
	base := os.DirFS(root)
	spec, err := fs.ReadFile(base, "docs/SPEC-TABLES.md")
	if err != nil {
		t.Fatal(err)
	}
	check := func(text string) []string {
		over := overlayFS{FS: base, over: map[string][]byte{"docs/SPEC-TABLES.md": []byte(text)}}
		_, findings := checkSpecPins(specPinsInput{fsys: over, spec: "docs/SPEC-TABLES.md", roadmap: "docs/roadmap.sexp", pins: specPinRegistry})
		return findings
	}
	if findings := check(string(spec)); len(findings) != 0 {
		t.Fatalf("the plant is out but the spec is already red: %v", findings)
	}
	const heading = "### 7.6 The write side: `Cook` and `CookMeasure`\n"
	if !strings.Contains(string(spec), heading) {
		t.Fatalf("the spec no longer carries %q; the plant needs it", heading)
	}
	planted := strings.Replace(string(spec), heading, heading+"A cook must be written with a marker. ", 1)
	found := false
	for _, f := range check(planted) {
		if strings.Contains(f, "normative sentence without a row id (section \"7.6") {
			found = true
			break
		}
	}
	if !found {
		t.Fatalf("the guard stayed green on an unpinned normative sentence in §7.6; findings: %v", check(planted))
	}
}
